// Jeden format wejścia dla każdego źródła: landing, Gmail, Fireflies, Gaius Meet, a później CRM.
// brief = { source, segment?, role?, email?, client?, text?, hasText }
const SEGMENTS = ['kancelaria', 'in-house', 'administracja'];
const ROLES = ['champion', 'zarzad'];
const input = $input.first().json;
const raw = input.body ?? input;
const pick = (v, allowed) => (allowed.includes(v) ? v : null);

const email = String(raw.email || '').trim().slice(0, 200);
const text = String(raw.text || raw.transcript || raw.notes || '').trim().slice(0, 60000);

// Bez tekstu zgadujemy segment tylko z domeny maila. To słaby sygnał, AI go nadpisze, gdy jest tekst.
const domain = email.split('@')[1]?.toLowerCase() || '';
const segmentFromDomain = /(^|\.)gov\.|\.gov$|gmina|powiat|urzad|um\.|ug\.|starostwo|(^|\.)bip\./.test(domain)
  ? 'administracja'
  : /kancelaria|legal|law|lex|adwokat|radca|prawn/.test(domain) ? 'kancelaria' : null;

return [{ json: {
  source: String(raw.source || 'landing'),
  segment: pick(raw.segment, SEGMENTS) ?? segmentFromDomain,
  role: pick(raw.role, ROLES),
  email: email || null,
  client: raw.client ? String(raw.client).slice(0, 200) : null,
  text,
  hasText: text.length > 0,
  receivedAt: new Date().toISOString(),
} }];

// Tu zapadają decyzje: segment, rola decydenta, oferta bazowa i treść.
// Domyślnie (nic nie wiemy): rola = zarząd, segment = dział prawny in-house.
const brief = $('Brief').first().json;
let ai = {};
try { ai = $('Analiza leada (AI)').first().json || {}; } catch (e) { ai = {}; }
if (ai.error) ai = {};

const SEGMENT_OK = ['kancelaria', 'in-house', 'administracja'];
const segment = [brief.segment, ai.segment].find((s) => SEGMENT_OK.includes(s)) ?? 'in-house';
const role = [brief.role, ai.role].find((r) => r === 'champion' || r === 'zarzad') ?? 'zarzad';

const SEGMENT = {
  kancelaria: { label: 'kancelarii', tag: 'kancelaria', who: 'Law firm' },
  'in-house': { label: 'działu prawnego', tag: 'dzial-prawny', who: 'In-house legal' },
  administracja: { label: 'urzędu', tag: 'administracja', who: 'Public administration' },
}[segment];

const client = brief.client || ai.client || null;
const concerns = Array.isArray(ai.concerns) ? ai.concerns.slice(0, 3) : [];
return [{ json: {
  known: brief.hasText && !!ai.summary,
  segment, role, client,
  person: ai.person || null,
  country: ai.country || null,
  concerns,
  summary: ai.summary || null,
  tag: SEGMENT.tag,
  segmentLabel: SEGMENT.label,
  who: [ai.person, client, SEGMENT.who].filter(Boolean).join(' · '),
  baseOfferId: 'gaius-vault-bazowa',
  offerName: `Oferta ${role === 'zarzad' ? 'dla zarządu' : 'dla championa'} · ${client || SEGMENT.who}`,
  brief: [ai.summary, concerns.length ? `Obawy: ${concerns.join('; ')}` : null,
          role === 'zarzad' ? 'Czyta zarząd: jeden odpowiedzialny partner, budżet, plan wdrożenia.'
                            : 'Czyta champion: argumenty dla zespołu i dla zarządu.'].filter(Boolean).join('\n'),
} }];

// Jedna pozycja = jedno żądanie PATCH do Offer Studio.
const plan = $('Plan oferty').first().json;
const offer = $input.first().json;
const segmentUseCases = $('Use case\'y segmentu').first().json.data || [];

// Które slajdy oferty bazowej pokazujemy komu.
const SHOW = {
  zarzad:   ['okladka', 'dlaczego', 'wdrozenie', 'use-case', 'cennik', 'kontakt'],
  champion: ['okladka', 'problemy', 'czym-jest', 'use-case', 'porownanie', 'dlaczego', 'cennik', 'kontakt'],
}[plan.role];

const COVER = plan.role === 'zarzad'
  ? { subtitle: `Jeden **odpowiedzialny partner** dla AI w Twojej ${plan.segmentLabel === 'urzędu' ? 'instytucji' : 'organizacji'}`,
      lead: 'Plan wdrożenia z przypisanymi właścicielami, stały koszt miesięczny i bezpieczny model startu.' }
  : { subtitle: 'Narzędzie, które Twój zespół **naprawdę otworzy w poniedziałek**',
      lead: 'Scenariusz pokazu dla zespołu i argumenty, z którymi pójdziesz do zarządu.' };

const ops = [{ path: `/api/offers/${offer.id}`, body: { data: {
  origin: 'n8n-lead', client: plan.client, segment: plan.segment, role: plan.role,
  concerns: plan.concerns, summary: plan.summary,
} } }];

for (const s of offer.slides || []) {
  const patch = { hidden: !SHOW.includes(s.frame) };
  if (s.frame === 'okladka') patch.data = COVER;
  if (s.frame === 'problemy') patch.data = { title: `Gdzie **ucieka** czas ${plan.segmentLabel}?` };
  // Use case'y segmentu tylko wtedy, gdy baza ma ich dość; inaczej zostają wszystkie.
  if (s.frame === 'use-case' && segmentUseCases.length >= 3) {
    patch.block_ids = [];
    patch.query = { type: 'use_case', tag: plan.tag, limit: 6 };
  }
  ops.push({ path: `/api/slides/${s.id}`, body: patch });
}
return ops.map((json) => ({ json }));

const offer = $('Kopia oferty bazowej').first().json;
const slide = (offer.slides || []).find((s) => s.frame === 'dlaczego');
return slide ? [{ json: { slideId: slide.id, brief: $('Plan oferty').first().json.brief } }] : [];

const plan = $('Plan oferty').first().json;
const offer = $('Kopia oferty bazowej').first().json;
const started = new Date($('Brief').first().json.receivedAt).getTime();
return [{ json: {
  offerId: offer.id,
  offerName: offer.name,
  known: plan.known,
  segment: plan.segment,
  role: plan.role,
  who: plan.who,
  client: plan.client,
  concerns: plan.concerns,
  summary: plan.summary,
  pdfPath: `/webhook/offer-pdf?id=${encodeURIComponent(offer.id)}`,
  ms: Date.now() - started,
} }];

// Na hackathonie zapis do CRM i alert na #sales są zamockowane. Tu podłączysz prawdziwe węzły.
const r = $input.first().json;
return [{ json: {
  crm: { stage: 'Oferta', offerId: r.offerId, who: r.who, nextActivity: 'follow-up call in 2 days' },
  discord: { channel: '#sales', text: `New offer ready for ${r.who}. Offer Studio: ${r.offerId}` },
} }];
